import SwiftUI
import SyncSpaceKit

struct MacNotesView: View { @EnvironmentObject private var state: SyncSpaceAppState; @State private var selected: Note.ID?; var body: some View { VStack(alignment: .leading) { HStack { Text("Notes").font(.largeTitle.bold()); Spacer(); Button("New Note", systemImage: "square.and.pencil") {}.disabled(true) }.padding(); HSplitView { List(state.recentNotes, selection: $selected) { note in VStack(alignment: .leading) { Text(note.title).font(.headline); Text(note.content).lineLimit(2).foregroundStyle(.secondary) }.tag(note.id) }.frame(minWidth: 240); if let note = state.recentNotes.first(where: { $0.id == selected }) { ScrollView { VStack(alignment: .leading, spacing: 14) { Text(note.title).font(.title.bold()); Text(note.createdAt.formatted()); Divider(); Text(note.content).textSelection(.enabled) }.frame(maxWidth: .infinity, alignment: .leading).padding() } } else { ContentUnavailableView("Select a note", systemImage: "note.text") } } } } }
struct MacSettingsView: View { @EnvironmentObject private var state: SyncSpaceAppState; var body: some View { Form { Section("Server") { TextField("Hostname or IP", text: $state.settings.serverHost); TextField("Port", value: $state.settings.serverPort, format: .number); Toggle("Use HTTPS", isOn: $state.settings.useHTTPS); Toggle("Auto-connect on launch", isOn: $state.settings.autoConnect); Toggle("Enable WebSocket updates", isOn: $state.settings.webSocketUpdates) }; Section("Preferences") { Toggle("Show notifications", isOn: $state.settings.showNotifications); Toggle("Save transfer history", isOn: $state.settings.saveTransferHistory); TextField("Device display name override", text: $state.settings.deviceNameOverride); Toggle("Debug logging", isOn: $state.settings.debugLogging) }; Section("Privacy") { Text("LAN-first, no analytics, and no background clipboard monitoring. File and clipboard sending always require an explicit action.").foregroundStyle(.secondary) }; HStack { Spacer(); Button("Save Settings") { state.saveSettings() }.buttonStyle(.borderedProminent) } }.formStyle(.grouped).padding().navigationTitle("Settings") } }
